// 题目富化后台接口封装。
//
// 路径与 ProblemEnrichmentController（web/controller/problem_enrichment.go）的方法名
// 按 AutoRegisterRoute 的驼峰转路径规则一一对应（与 permission.ts 同一约定）。
import httpRequest from "@/apis/axios-api";

import type { CodeResult } from "@/types/request";
import type {
  CuratorContext,
  EnrichCallItem,
  EnrichConsistencyReport,
  EnrichOverview,
  EnrichPage,
  EnrichReviewItem,
  EnrichStateStatus,
  EnrichStateItem,
  EnrichSummaryPayload,
  EnrichTag,
  EnrichWorkerConfig,
  SaveHumanAnnotationRequest,
  TagAlias,
} from "@/types/problem-enrichment";

// ── 状态监控 ──

export function GetEnrichStateList(
  status: EnrichStateStatus[] | null,
  page: number,
  pageSize: number
): Promise<CodeResult<EnrichPage<EnrichStateItem>>> {
  return httpRequest<unknown, CodeResult<EnrichPage<EnrichStateItem>>>({
    url: "/problem/enrichment/state/list",
    method: "get",
    params: {
      status: status && status.length > 0 ? status.join(",") : undefined,
      page,
      page_size: pageSize,
    },
  });
}

export function GetEnrichWorkerConfig(): Promise<CodeResult<EnrichWorkerConfig>> {
  return httpRequest<unknown, CodeResult<EnrichWorkerConfig>>({
    url: "/problem/enrichment/worker/config",
    method: "get",
  });
}

export function PostEnrichRequeue(problemId: number): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/requeue",
    method: "post",
    data: { problem_id: problemId },
  });
}

export function PostEnrichBackfill(): Promise<CodeResult<{ inserted: number }>> {
  return httpRequest<unknown, CodeResult<{ inserted: number }>>({
    url: "/problem/enrichment/backfill",
    method: "post",
  });
}

// 运维总览仪表盘（状态分布/覆盖率/当日成本/worker 健康/阶段耗时）
export function GetEnrichOverview(): Promise<CodeResult<EnrichOverview>> {
  return httpRequest<unknown, CodeResult<EnrichOverview>>({
    url: "/problem/enrichment/overview",
    method: "get",
  });
}

// 调用账本分页（problemId/stage/status 均可选过滤）
export function GetEnrichCallList(
  params: { problem_id?: number; stage?: string; status?: string; page: number; page_size: number }
): Promise<CodeResult<EnrichPage<EnrichCallItem>>> {
  return httpRequest<unknown, CodeResult<EnrichPage<EnrichCallItem>>>({
    url: "/problem/enrichment/call/list",
    method: "get",
    params,
  });
}

// 手动重判单题（强制：处理中/成功/失败都重新入队，人工定稿类型保留）
export function PostEnrichRejudge(problemId: number): Promise<CodeResult<null>> {
  return httpRequest<unknown, CodeResult<null>>({
    url: "/problem/enrichment/rejudge",
    method: "post",
    data: { problem_id: problemId },
  });
}

// 一键重判全部失败终态题目
export function PostEnrichRejudgeFailed(): Promise<CodeResult<{ reset: number }>> {
  return httpRequest<unknown, CodeResult<{ reset: number }>>({
    url: "/problem/enrichment/rejudge/failed",
    method: "post",
  });
}

