// 按名称模糊搜索标签（合并目标远程选择，默认只搜正式词）
export function GetEnrichTagSearch(
  keyword: string,
  limit = 20,
  status?: number[]
): Promise<CodeResult<{ list: EnrichTag[] }>> {
  return httpRequest<unknown, CodeResult<{ list: EnrichTag[] }>>({
    url: "/problem/enrichment/tag/search",
    method: "get",
    params: {
      keyword,
      limit,
      status: status && status.length > 0 ? status.join(",") : undefined,
    },
  });
}

